WITH base AS (SELECT *, CASE WHEN status IN ('CLOSED', 'OPEN') THEN 'Group A' ELSE 'Other' END AS status_group, CONCAT(status, ', ', account_type) AS status_account_type FROM accounts WHERE opened_date > DATE '2023-04-29' AND customer_id IS NOT NULL) SELECT * FROM (SELECT status, customer_id, account_type, balance FROM base) src PIVOT (MAX(balance) AS value_sum, COUNT(1) AS cnt FOR account_type IN ('LOAN' AS loan, 'CREDIT' AS credit))
